from pathlib import Path
import json,hashlib,importlib.util
HERE=Path(__file__).parent
spec=importlib.util.spec_from_file_location('endpoint_oracle',HERE.parent/'endpoint_oracle_acquisition_20261028/oracle_and_endpoint_fit_v1.py');o=importlib.util.module_from_spec(spec);spec.loader.exec_module(o)
rows=[]
for p in sorted(HERE.glob('*_v1.json')):
 j=json.loads(p.read_text())
 if 'same_elapsed_unencoded' not in j:continue
