 values=[1-o.oracle(at(a['results'])['logical_PTM'])[1] for a in j['same_elapsed_unencoded']]
 rows.append({'source_file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'eta':j['eta'],'background_integral':j['integrated_background_strength_EC_window'],'rate':j['background_rate_per_reference_time'],'EC_time':j['timing']['total_EC_time'],'total_round_time_declared':j['timing']['total_EC_time']+2,'measurement_duration':j['clock']['measure'],'T':32,'encoded_infidelity':at(j['encoded'])['entanglement_infidelity'],'best_single_site_full_CPTP_endpoint_oracle_infidelity':min(values),'all_site_endpoint_oracle_infidelities':values,'encoded_lower_infidelity_than_best_endpoint_oracle':at(j['encoded'])['entanglement_infidelity']<min(values)})
